) -> None:
    client = _client(config)
    seasons = config.get("scope", {}).get("seasons", {})
    start, end = seasons.get("start"), seasons.get("end")
    for season in range(int(start), int(end) + 1):
        s = _run_one_season(conn, client, config, season, resume=resume)
        label = "resume-backfill" if resume else "backfill"
        print(f"[{label}] {s}")


def run_season(conn, config, season: int) -> None:
